#!/usr/bin/env python3
"""Deterministically generate the PDF fixtures used by the ticket-17 backend tests.

Run from anywhere:

    python3 tests/fixtures/pdf/generate.py

Only the Python standard library is used, plus the pypdf wheel vendored at
``backend/attachments/pdf/pypdf-6.21.0-py3-none-any.whl`` so the fixtures stay
reproducible without adding an environment dependency.

Every output is byte-for-byte stable across runs: pypdf's random document /ID
is pinned to a fixed value so regenerating never produces a spurious diff.
"""

from __future__ import annotations

import io
import sys
from pathlib import Path

# --- vendored pypdf ---------------------------------------------------------
HERE = Path(__file__).resolve().parent
REPO_ROOT = HERE.parents[2]
WHEEL = REPO_ROOT / "backend/attachments/pdf/pypdf-6.21.0-py3-none-any.whl"

if not WHEEL.is_file():
    raise SystemExit(f"pypdf wheel not found: {WHEEL}")

# A zipimport path must be the wheel itself, not the containing directory.
sys.path.insert(0, str(WHEEL))

from pypdf import PdfWriter  # noqa: E402
from pypdf.generic import (  # noqa: E402
    ArrayObject,
    ByteStringObject,
    DecodedStreamObject,
    DictionaryObject,
    NameObject,
)

# Fixed so repeated runs emit identical bytes.
FIXED_ID = b"0170ddfa17b0c4e4c9f0a4d8f7b6e5a4"

PAGE_WIDTH = 200
PAGE_HEIGHT = 200


def _writer() -> PdfWriter:
    """A writer pinned to a fixed /ID so output bytes stay stable across runs."""
    writer = PdfWriter()
    writer._ID = ArrayObject([ByteStringObject(FIXED_ID), ByteStringObject(FIXED_ID)])
    return writer


def _content_stream(text: str) -> DecodedStreamObject:
    """A content stream that paints ``text`` literally at a fixed position."""
    stream = DecodedStreamObject()
    body = "\n".join(["BT", "/F1 12 Tf", "12 150 Td", f"({text}) Tj", "ET"])
    stream.set_data(body.encode("ascii"))
    return stream


def _add_text_page(writer: PdfWriter, text: str) -> None:
    """Append a page whose only text is ``text``, using an explicit Type1 font."""
    page = writer.add_blank_page(PAGE_WIDTH, PAGE_HEIGHT)

    font = DecodedStreamObject()
    font.update(
        {
            NameObject("/Type"): NameObject("/Font"),
            NameObject("/Subtype"): NameObject("/Type1"),
            NameObject("/BaseFont"): NameObject("/Helvetica"),
            NameObject("/Encoding"): NameObject("/WinAnsiEncoding"),
        }
    )
    font_ref = writer._add_object(font)

    page[NameObject("/Resources")] = DictionaryObject(
        {NameObject("/Font"): DictionaryObject({NameObject("/F1"): font_ref})}
    )
    page[NameObject("/Contents")] = writer._add_object(_content_stream(text))


def write_text_pdf(path: Path) -> None:
    """Two pages carrying independent, page-addressable literals."""
    writer = _writer()
    _add_text_page(writer, "PAGE_ONE_ALPHA")
    _add_text_page(writer, "PAGE_TWO_BETA")
    with path.open("wb") as handle:
        writer.write(handle)


def write_empty_pdf(path: Path) -> None:
    """One structurally valid page with no text at all."""
    writer = _writer()
    writer.add_blank_page(PAGE_WIDTH, PAGE_HEIGHT)
    with path.open("wb") as handle:
        writer.write(handle)


def write_encrypted_pdf(path: Path) -> None:
    """Standard-password encrypted document; unreadable without the password."""
    writer = _writer()
    _add_text_page(writer, "SECRET_PAGE_ALPHA")
    writer.encrypt("fixture-password")
    with path.open("wb") as handle:
        writer.write(handle)


def write_many_pages_pdf(path: Path) -> None:
    """501 blank pages, for page-count and per-page read budget checks."""
    writer = _writer()
    for _ in range(501):
        writer.add_blank_page(PAGE_WIDTH, PAGE_HEIGHT)
    with path.open("wb") as handle:
        writer.write(handle)


def write_partial_pdf(path: Path) -> None:
    """Page 1 extracts cleanly; page 2's content stream is unreadable.

    A valid two-page document is written first, then only page 2's content stream
    bytes are overwritten in place with invalid operators. The replacement is the
    exact same length, so the catalog, page tree and every xref offset stay valid:
    the page count and page 1's text remain readable while reading page 2 raises
    ``PdfReadError``.
    """
    writer = _writer()
    _add_text_page(writer, "PAGE_ONE_ALPHA")
    _add_text_page(writer, "PAGE_TWO_BETA")

    raw = io.BytesIO()
    writer.write(raw)
    data = bytearray(raw.getvalue())

    damaged = _content_stream("PAGE_TWO_BETA").get_data()
    index = data.rfind(damaged)
    if index < 0 or index < len(damaged):  # rfind returns -1 when absent
        raise RuntimeError("page 2 content stream not found in generated bytes")

    # Non-token bytes: not valid PDF operators, and exactly the same length so
    # every xref offset below stays valid.
    filler = b"\xff\xfe\xfd\xfc"
    data[index : index + len(damaged)] = (filler * (len(damaged) // len(filler) + 1))[: len(damaged)]
    path.write_bytes(bytes(data))


def write_damaged_pdf(path: Path) -> None:
    """Not a PDF at all: bytes that must fail to open."""
    path.write_bytes(b"%PDF-1.7\nthis is not a pdf body, only damaged bytes\n%%EOF\n")


FIXTURES = (
    ("text.pdf", write_text_pdf),
    ("empty.pdf", write_empty_pdf),
    ("encrypted.pdf", write_encrypted_pdf),
    ("damaged.pdf", write_damaged_pdf),
    ("many-pages.pdf", write_many_pages_pdf),
    ("partial.pdf", write_partial_pdf),
)


def main() -> int:
    for name, build in FIXTURES:
        target = HERE / name
        build(target)
        print(f"{name}: {target.stat().st_size} bytes")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
